import Foundation
import SwiftUI

@MainActor final class ShopModel:ObservableObject {
    @Published var products:[Product]=[]
    @Published var cart:[CartItem]=[]
    @Published var orders:[Order]=[]
    @Published var state="loading"
    @Published var search=""
    @Published var selected:Product?
    @Published var signedIn=false
    @Published var privacyRevision=0
    @Published var privacyExportURL:URL?
    @Published var appLanguage=UserDefaults.standard.string(forKey:"app-language") ?? Locale.current.identifier
    @Published var aiLanguage=UserDefaults.standard.string(forKey:"ai-language") ?? Locale.current.language.languageCode?.identifier ?? "en"
    struct InvoicePresentation:Identifiable {let review:AppleBuyerJourney.Review;let session:ShopSession;let revision:Int;let url:URL;var id:String{review.key}}
    @Published var invoicePresentation:InvoicePresentation?
    let api:APIClient,queue:OfflineQueue,invoiceHandoffs:InvoiceHandoffJournal,journey:AppleBuyerJourney
    private var presentedSession:ShopSession?
    private var operationRevision=0
    @Published private(set) var mutationBusy=false
    @Published var profileName=""
    @Published var profileRecipient=""
    @Published var profileAddress=""
    @Published var profileCity=""
    @Published var profileCountry=""
    struct OrderActionPresentation:Identifiable {let id=UUID();let order:Order;let action:String;let title:String;let session:ShopSession;let revision:Int}
    @Published var orderActionPresentation:OrderActionPresentation?
    private var handoffPresentationRevision=0
    func cancelInvoicePresentation(){handoffPresentationRevision+=1;invoicePresentation=nil;orderActionPresentation=nil}
    init(api:APIClient?=nil,queue:OfflineQueue?=nil,invoiceHandoffs:InvoiceHandoffJournal?=nil,journey:AppleBuyerJourney?=nil){self.api=api ?? APIClient();self.queue=queue ?? OfflineQueue();self.invoiceHandoffs=invoiceHandoffs ?? InvoiceHandoffJournal();self.journey=journey ?? AppleBuyerJourney();cart=(try? self.journey.guest()) ?? [];self.api.onSessionChanged={[weak self] in self?.reconcileIdentity()};Task{try? await self.api.restoreNative();self.reconcileIdentity()};Task{await loadCatalog()};Task{[weak self] in while !Task.isCancelled{try? await Task.sleep(for:.seconds(1));guard let self else{return};if self.presentedSession != self.api.currentSession{self.reconcileIdentity()}}}}
    private func reconcileIdentity(){let current=api.currentSession;guard current != presentedSession else{return};cancelInvoicePresentation();operationRevision+=1;mutationBusy=false;cart=[];orders=[];selected=nil;privacyRevision+=1;if let url=privacyExportURL{try? FileManager.default.removeItem(at:url)};privacyExportURL=nil;clearProfilePresentation();presentedSession=current;signedIn=current != nil;if let current{do{cart=try journey.load(current.account).items;Task{await loadOrders();await resumeOriginalOrder()}}catch{state="security_error"}}}
    func sceneActive(){reconcileIdentity();Task{await resumeOriginalOrder()}}
    func setLanguage(_ value:String){appLanguage=value;UserDefaults.standard.set(value,forKey:"app-language")}
    func setAILanguage(_ value:String){aiLanguage=value;UserDefaults.standard.set(value,forKey:"ai-language")}
    private func failure(_ error:Error){if let error=error as? ShopError{if error == .contextChanged{if signedIn && api.currentSession==nil{signOut()};return};if error == .signedOut{signOut();return}};state="unavailable"}
    func signOut(){cancelInvoicePresentation();api.invalidate();operationRevision+=1;mutationBusy=false;presentedSession=nil;signedIn=false;cart=[];orders=[];selected=nil;privacyRevision+=1;if let url=privacyExportURL{try? FileManager.default.removeItem(at:url)};privacyExportURL=nil;clearProfilePresentation();do{try api.disconnectNative();state=""}catch{state="security_error"}}
    func loadCatalog()async{state="loading";do{let r:CatalogResponse=try await api.request("products?q=\(search.addingPercentEncoding(withAllowedCharacters:.urlQueryAllowed) ?? "")");products=r.products;state=products.isEmpty ? "empty_catalog":""}catch{failure(error)}}
    func loadOrders()async{guard signedIn else{return};do{let check=try api.capture();let r:OrdersResponse=try await api.request("orders");try check();guard let account=api.currentSession?.account else{throw ShopError.signedOut};try r.orders.forEach{try AppleBuyerReceipt.validate($0,account:account)};orders=r.orders}catch{failure(error)}}
    func add(_ product:Product,_ variant:Variant){guard !mutationBusy else{return};var next=cart;if let index=next.firstIndex(where:{$0.productID==product.productID && $0.variantID==variant.variantID}){next[index].quantity+=1}else{next.append(.init(productID:product.productID,variantID:variant.variantID,quantity:1))};do{if let account=api.currentSession?.account{try journey.edit(account,items:next)}else{try journey.editGuest(next)};cart=next}catch{failure(error)}}
    func removeCart(_ item:CartItem){guard !mutationBusy else{return};do{let next=cart.filter{$0.id != item.id};if let account=api.currentSession?.account{try journey.edit(account,items:next)};cart=next}catch{failure(error)}}
    func syncCart(){guard signedIn,!mutationBusy else{return};mutationBusy=true;let revision=operationRevision;Task{defer{if revision==operationRevision{mutationBusy=false}};do{let check=try api.capture();guard let account=api.currentSession?.account else{throw ShopError.signedOut};let remote=try await api.raw("cart",method:"GET",json:[:]);try check();try journey.reconcileCart(remote,account:account);let draft=try journey.load(account);if draft.dirty {let pending=try journey.prepareCart(account);let body:[String:Any]=["Items":pending.items.map{["ProductID":$0.productID,"VariantID":$0.variantID,"Quantity":$0.quantity] as [String:Any]},"ExpectedRevision":pending.expected,"IdempotencyKey":pending.key];let saved=try await api.raw("cart",method:"PUT",json:body);try check();try journey.reconcileCart(saved,account:account)};cart=try journey.load(account).items;state=""}catch{failure(error)}}}
    func signIn(){cancelInvoicePresentation();api.invalidate();operationRevision+=1;mutationBusy=false;Task{do{try await WalletAuth.begin(api:api)}catch{failure(error)}}}
    func walletCallback(_ url:URL){if AppleBuyerJourney.wakeHint(url){Task{await resumeOriginalOrder()};return};guard url.scheme=="ynxshop",url.host=="wallet-auth",url.path=="/callback" else{return};Task{do{try await WalletAuth.complete(url,api:api);reconcileIdentity();state=signedIn ? "wallet_active":"security_error";await loadOrders();await resumeOriginalOrder()}catch{failure(error)}}}
    private func mutation(path:String,input:[String:Any],receipt:@escaping ([String:Any])throws->Void){
        guard signedIn,!mutationBusy else{return}
        do{let authorization=try api.capture(),view=handoffPresentationRevision;let check:()throws->Void={try authorization();guard view==self.handoffPresentationRevision else{throw ShopError.contextChanged}};guard let account=api.currentSession?.account else{throw ShopError.signedOut};guard try !queue.load(account:account).contains(where:{$0.path==path}) else{throw ShopError.unresolvedMutation};let item=try queue.prepareUnsent(account:account,path:path,input:input);mutationBusy=true;let revision=operationRevision
            Task{defer{if revision==operationRevision{mutationBusy=false}};do{let json=try JSONSerialization.jsonObject(with:item.body) as? [String:Any];guard let json else{throw ShopError.security};try check();let result=try await api.raw(item.path,method:item.method,json:json,beforeDispatch:{try check();try self.queue.beginDispatch(item)});try check();_ = try AppleBuyerReceipt.decode(result,account:account);try receipt(result);try queue.confirmedTracked(item);await loadOrders()}catch{do{try queue.markUnknown(item)}catch{failure(error);return};if let err=error as? ShopError,err == .contextChanged || err == .signedOut{failure(error)}else{state="queued_offline"}}}
        }catch{failure(error)}
    }
    func checkout(recipient:String,address:String,city:String,country:String){guard signedIn else{signIn();return};guard !mutationBusy else{return};do{let check=try api.capture();guard let session=api.currentSession else{throw ShopError.signedOut};let draft=try journey.load(session.account);guard !draft.dirty,draft.cartIntent==nil,let cartRevision=draft.revision,!draft.items.isEmpty,!recipient.isEmpty,!address.isEmpty,!country.isEmpty else{throw ShopError.unresolvedMutation};let stores=Set(draft.items.compactMap{item in products.first(where:{$0.productID==item.productID})?.storeID});guard stores.count==1,let store=stores.first,draft.items.allSatisfy({item in products.contains{$0.productID==item.productID}}) else{throw ShopError.security};let old=try queue.load(account:session.account).contains{$0.path=="orders"};let body:[String:Any]=["StoreID":store,"Items":draft.items.map{["ProductID":$0.productID,"VariantID":$0.variantID,"Quantity":$0.quantity] as [String:Any]},"CartRevision":cartRevision,"Address":["Recipient":recipient,"Line1":address,"City":city,"Country":country]];let item=try queue.prepare(account:session.account,path:"orders",input:body);try journey.checkoutPrepared(session.account,item:item,existing:old);mutationBusy=true;let revision=operationRevision;Task{defer{if revision==operationRevision{mutationBusy=false}};do{guard let input=try JSONSerialization.jsonObject(with:item.body) as? [String:Any] else{throw ShopError.security};let result=try await api.raw("orders",json:input,beforeDispatch:{try check();try self.journey.checkoutDispatch(session.account,item:item)});try check();let order=try AppleBuyerReceipt.decode(result,account:session.account);try journey.checkoutConfirmed(session.account,item:item,order:order);try queue.confirmed(item);cart=try journey.load(session.account).items;await loadOrders()}catch{failure(error)}}}catch{failure(error)}}
    func recoverCheckout(){guard signedIn,!mutationBusy else{return};mutationBusy=true;let revision=operationRevision;Task{defer{if revision==operationRevision{mutationBusy=false}};do{let check=try api.capture();guard let account=api.currentSession?.account,let item=try queue.load(account:account).first(where:{$0.path=="orders"}),let body=try JSONSerialization.jsonObject(with:item.body) as? [String:Any],let key=body["IdempotencyKey"] as? String else{throw ShopError.unresolvedMutation};let result=try await api.raw("orders/intent-lookup",json:["IdempotencyKey":key]);try check();let order=try AppleBuyerReceipt.decode(result,account:account);try journey.checkoutConfirmed(account,item:item,order:order);try queue.confirmed(item);cart=try journey.load(account).items;await loadOrders()}catch{failure(error)}}}
    func beginOrderAction(_ order:Order,_ action:String,title:String){
        guard signedIn,!mutationBusy,let session=api.currentSession else{return}
        do{_ = try api.capture();try AppleBuyerReceipt.validate(order,account:session.account);guard BuyerOrderActionInput.allowed(order.status,action) else{throw ShopError.invalidResponse};cancelInvoicePresentation();orderActionPresentation=OrderActionPresentation(order:order,action:action,title:title,session:session,revision:operationRevision)}catch{failure(error)}
    }
    func submitOrderAction(_ presentation:OrderActionPresentation,rating:Int,reason:String,detail:String)->Bool {
        guard orderActionPresentation?.id==presentation.id,api.currentSession==presentation.session,operationRevision==presentation.revision,signedIn,!mutationBusy else{orderActionPresentation=nil;return false}
        do{let check=try api.capture();try check();guard try !queue.load(account:presentation.session.account).contains(where:{$0.path=="orders/\(presentation.order.orderID)/transition"}) else{state="order_request_pending";return false};try AppleBuyerReceipt.validate(presentation.order,account:presentation.session.account);let input=try BuyerOrderActionInput.build(status:presentation.order.status,action:presentation.action,rating:rating,reason:reason,detail:detail);mutation(path:"orders/\(presentation.order.orderID)/transition",input:input){value in guard value["ID"] as? String==presentation.order.orderID else{throw ShopError.security}};if mutationBusy{orderActionPresentation=nil;return true};return false}catch{state="order_input_required";return false}
    }
    func checkPayment(_ order:Order){guard signedIn else{return};Task{do{let check=try api.capture();_ = try await api.raw("orders/\(order.orderID)/confirm-payment",json:[:]);try check();await resumeOriginalOrder();await loadOrders()}catch{failure(error)}}}
    func pay(_ order:Order){guard signedIn,!mutationBusy else{return};do{let check=try api.capture();guard let session=api.currentSession else{throw ShopError.signedOut};try AppleBuyerReceipt.validate(order,account:session.account);let legacy=try queue.originalHandoff(account:session.account,path:"orders/\(order.orderID)/pay-handoff");let originalKey=try legacy.map{try JSONSerialization.jsonObject(with:$0.body) as? [String:Any]}.flatMap{$0?["IdempotencyKey"] as? String};let existed=try invoiceHandoffs.existing(account:session.account,order:order);let original=try invoiceHandoffs.prepare(account:session.account,order:order,originalKey:originalKey);let review=try journey.prepareReview(session.account,order:order,original:original,existing:existed || legacy != nil);mutationBusy=true;let revision=operationRevision,presentation=handoffPresentationRevision;Task{defer{if revision==operationRevision{mutationBusy=false}};do{let create=review.phase=="prepared";let result=try await api.raw("orders/\(original.orderID)/pay-handoff",method:create ? "POST":"GET",json:create ? ["IdempotencyKey":original.record.key]:[:],beforeDispatch:create ? {try check();try self.journey.reviewDispatch(session.account,review:review)}:nil);try check();guard presentation==handoffPresentationRevision else{return};let url=try invoiceHandoffs.reviewURL(original,response:result);let received=try journey.reviewReceived(session.account,review:review,response:result,url:url);invoicePresentation=InvoicePresentation(review:received,session:session,revision:presentation,url:url)}catch{failure(error)}}}catch{failure(error)}}
    func openReviewedInvoice(){guard let presentation=invoicePresentation else{return};invoicePresentation=nil;Task{do{let check=try api.capture();guard api.currentSession==presentation.session,presentation.revision==handoffPresentationRevision else{throw ShopError.contextChanged};try await api.reviewInvoice(presentation.url,expected:presentation.session);try check();try journey.reviewOpened(presentation.session.account,review:presentation.review);state="payment_pending"}catch{failure(error)}}}
    func resumeOriginalOrder()async {guard signedIn else{return};do{let check=try api.capture();guard let account=api.currentSession?.account,let review=try journey.load(account).review else{return};let value=try await api.raw("orders/\(review.original.orderID)",method:"GET",json:[:]);try check();let order=try AppleBuyerReceipt.decode(value,account:account);try journey.observed(account,order:order,journal:invoiceHandoffs);await loadOrders()}catch{failure(error)}}
    func retryPending(){
        guard signedIn,!mutationBusy else{return};mutationBusy=true;let revision=operationRevision,view=handoffPresentationRevision
        Task{defer{if revision==operationRevision{mutationBusy=false}};do{let authorization=try api.capture();let check:()throws->Void={try authorization();guard view==self.handoffPresentationRevision else{throw ShopError.contextChanged}};guard let session=api.currentSession else{throw ShopError.signedOut};let originals=try queue.load(account:session.account)
            for item in originals{try check();guard let body=try JSONSerialization.jsonObject(with:item.body) as? [String:Any] else{throw ShopError.security}
                if item.path.hasSuffix("/transition"){do{if try queue.dispatchPhase(item)=="prepared"{let result=try await api.raw(item.path,method:item.method,json:body,beforeDispatch:{try check();try self.queue.beginDispatch(item)});try check();let order=try AppleBuyerReceipt.decode(result,account:session.account);guard item.path=="orders/\(order.orderID)/transition" else{throw ShopError.security}}else{let result=try await api.raw(item.path+"-intent-lookup",json:body,beforeDispatch:{try check()});try check();_ = try BuyerTransitionRecovery.receipt(result,session:session,item:item)};try queue.confirmedTracked(item)}catch{try queue.markUnknown(item);throw error}}
                else if item.path=="orders"{guard let key=body["IdempotencyKey"] as? String else{throw ShopError.security};let result=try await api.raw("orders/intent-lookup",json:["IdempotencyKey":key],beforeDispatch:{try check()});try check();let order=try AppleBuyerReceipt.decode(result,account:session.account);try journey.checkoutConfirmed(session.account,item:item,order:order);try queue.confirmed(item);cart=try journey.load(session.account).items}
            };await loadOrders();state=""
        }catch{failure(error)}}
    }
    private func clearProfilePresentation(){profileName="";profileRecipient="";profileAddress="";profileCity="";profileCountry=""}
    func loadProfile(){guard signedIn else{return};Task{do{let check=try api.capture();let value=try await api.raw("profile",method:"GET",json:[:]);try check();guard let profile=value["profile"] as? [String:Any] else{throw ShopError.invalidResponse};let address=(profile["Addresses"] as? [[String:Any]])?.first ?? [:];profileName=profile["DisplayName"] as? String ?? "";profileRecipient=address["Recipient"] as? String ?? "";profileAddress=address["Line1"] as? String ?? "";profileCity=address["City"] as? String ?? "";profileCountry=address["Country"] as? String ?? ""}catch{failure(error)}}}
    func saveProfile(){guard signedIn,!mutationBusy else{return};let input:[String:Any]=["DisplayName":profileName,"Addresses":[["Recipient":profileRecipient,"Line1":profileAddress,"City":profileCity,"Country":profileCountry]]];mutationBusy=true;let revision=operationRevision;Task{defer{if revision==operationRevision{mutationBusy=false}};do{let check=try api.capture();_ = try await api.raw("profile",method:"PUT",json:input);try check();state="profile_saved"}catch{failure(error)}}}
    func exportPrivacyData(){guard signedIn else{signIn();return};Task{do{let check=try api.capture();let data=try await api.data("privacy/export");try check();let url=FileManager.default.temporaryDirectory.appendingPathComponent("ynx-shop-data-\(UUID().uuidString).json");try data.write(to:url,options:.atomic);try FileManager.default.setAttributes([.posixPermissions:0o600],ofItemAtPath:url.path);privacyExportURL=url;state="privacy_export_ready"}catch{failure(error)}}}
    func deletePrivacyData(_ confirmation:String){guard signedIn else{signIn();return};guard confirmation=="DELETE_MY_SHOP_DATA" else{state="privacy_exact_required";return};guard !mutationBusy else{state="queued_offline";return};mutationBusy=true;let revision=operationRevision;Task{defer{if revision==operationRevision{mutationBusy=false}};do{let check=try api.capture();guard let account=api.currentSession?.account,try !queue.hasPending(account:account),try !invoiceHandoffs.hasPending(account:account),try journey.deletionPermitted(account) else{throw ShopError.unresolvedMutation};_ = try await api.raw("privacy/delete",json:["confirmation":confirmation]);try check();try journey.deletedDraft(account);clearProfilePresentation();cart=[];orders=[];if let url=privacyExportURL{try? FileManager.default.removeItem(at:url)};privacyExportURL=nil;privacyRevision+=1;state="privacy_deleted"}catch{if let error=error as? ShopError,error == .contextChanged || error == .signedOut{failure(error)}else{state="privacy_delete_failed"}}}}
    func runAI(workflow:String,summary:String){guard signedIn else{signIn();return};Task{do{let check=try api.capture();let job=try await api.raw("ai/jobs",json:["Workflow":workflow,"ContextClasses":["public_catalog"],"ContextSummary":"\(summary); outputLanguage=\(aiLanguage)","EstimateUnits":1,"PermissionGranted":true,"IdempotencyKey":UUID().uuidString]);try check();guard let id=job["ID"] as? String else{throw ShopError.invalidResponse};let result=try await api.raw("ai/jobs/\(id)/run",json:[:]);try check();state=(result["Result"] as? String) ?? "unavailable"}catch{failure(error)}}}
}
